<template><main class="grid min-h-screen place-items-center bg-slate-950 p-5 text-slate-100"><form class="w-full max-w-md rounded-3xl border border-white/10 bg-white/5 p-8" @submit.prevent="accept"><p class="text-xs uppercase tracking-[.25em] text-amber-300">Invitación empresarial</p><h1 class="mt-2 text-3xl font-semibold">Define tu contraseña</h1><input v-model="password" type="password" minlength="8" required class="mt-7 w-full rounded-xl border border-white/10 bg-slate-900 px-4 py-3" placeholder="Mínimo 8 caracteres" /><input v-model="confirmation" type="password" minlength="8" required class="mt-4 w-full rounded-xl border border-white/10 bg-slate-900 px-4 py-3" placeholder="Confirmar contraseña" /><p v-if="message" class="mt-4 text-sm" :class="done?'text-emerald-300':'text-red-300'">{{message}}</p><button :disabled="done" class="mt-6 w-full rounded-xl bg-amber-400 px-4 py-3 font-semibold text-slate-950 disabled:opacity-50">Activar tenant</button></form></main></template>
<script setup lang="ts">import{ref}from'vue';import{useRoute}from'vue-router';import{platformApi}from'@/services/platformApi';const route=useRoute();const password=ref('');const confirmation=ref('');const message=ref('');const done=ref(false);async function accept(){if(password.value!==confirmation.value){message.value='Las contraseñas no coinciden.';return}try{await platformApi.acceptInvitation({invitationId:String(route.query.invitationId||''),token:String(route.query.token||''),password:password.value});done.value=true;message.value='Cuenta activada. Ya puedes iniciar sesión.'}catch(e){message.value=e instanceof Error?e.message:'No fue posible aceptar la invitación'}}</script>
